#include<bits/stdc++.h>
#define int long long
using namespace std;
int a[15555],b[15555];
int dp[15555][22]; 
void akioi_and_aknoi_andf_akagc(){
	int n;
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i];
	}
	memset(dp,0,sizeof(dp));
	memset(b,0,sizeof(b));
	for(int i=0;i<=20;i++){
		for(int j=1;j<=n+2;j++){
			dp[j][i]=n+1;
		}
	}
	for(int i=n;i>=1;i--){
		if(b[a[i]]!=0){
			dp[i][0]=b[a[i]];
		}
		b[a[i]]=i;
	}
	for(int j=1;j<=20;j++){
		for(int i=1;i<=n;i++){
			dp[i][j]=dp[dp[i][j-1]+1][j-1];
		}
	}
	int q;
	cin>>q;
	while(q--){
		int l,r;
		cin>>l>>r;
		int ans=0;
		while(l<=r){
			for(int i=20;i>=0;i--){
				if(dp[l][i]<=r){
					l=dp[l][i]+1;
				}
			}
			if(l<=r){
				l++;
				ans++;
			}
//			cout<<l<<" "<<r<<endl;
		}
		cout<<ans<<endl;
	}
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int t;
	cin>>t;
	while(t--){
		akioi_and_aknoi_andf_akagc();
	}
    return 0;
}
